   "  const cont = document.getElementById('rhContenido');\n  cont.innerHTML = `<p style=\"color:var(--muted);\">Cargando…</p>`;\n  const query = VACACIONES_AJUSTE_FILTRO === 'todas' ? '' : `?estado=${VACACIONES_AJUSTE_FILTRO}`;\n  const lista = await api(`/api/rh/vacaciones-ajuste${query}`);\n  const BADGE_ESTADO_VAC = {\n    pendiente: '<span class=\"rol-tag\">⏳ Pendiente</span>',\n    aprobada: '<span class=\"badge baja\">✅ Aprobada</span>',\n    rechazada: '<span class=\"badge urgente\">❌ Rechazada</span>',\n  };\n  cont.innerHTML = `\n    <p style=\"font-size:12px; color:var(--muted); margin-bottom:12px;\">\n      Vacaciones pedidas desde la app por empleados con su antigüedad corregida (ver Empleados (Microsip) → Ver ficha → Ajuste de antigüedad).\n      No se descuentan de su saldo hasta que las apruebes aquí.\n    </p>\n    <div class=\"admin-tabs\" style=\"margin-bottom:12px;\">\n      <button class=\"admin-tab ${VACACIONES_AJUSTE_FILTRO === 'pendiente' ? 'active' : ''}\" onclick=\"VACACIONES_AJUSTE_FILTRO='pendiente'; renderVacacionesAjusteRH();\">⏳ Pendientes</button>\n",
   "  const cont = document.getElementById('rhContenido');\n  cont.innerHTML = `<p style=\"color:var(--muted);\">Cargando…</p>`;\n  const query = VACACIONES_AJUSTE_FILTRO === 'todas' ? '' : `?estado=${VACACIONES_AJUSTE_FILTRO}`;\n  const [lista, listaMs] = await Promise.all([\n    api(`/api/rh/vacaciones-ajuste${query}`),\n    api(`/api/rh/vacaciones-microsip?estado=${VACACIONES_AJUSTE_FILTRO}`).catch(() => []),\n  ]);\n  const BADGE_ESTADO_VAC = {\n    pendiente: '<span class=\"rol-tag\">⏳ Pendiente</span>',\n    aprobada: '<span class=\"badge baja\">✅ Aprobada</span>',\n    rechazada: '<span class=\"badge urgente\">❌ Rechazada</span>',\n    cancelada: '<span class=\"rol-tag\">Cancelada</span>',\n  };\n  const tablaMs = listaMs.length || VACACIONES_AJUSTE_FILTRO === 'pendiente' ? `\n    <h3 style=\"margin:14px 0 6px;\">🏖️ Pedidas desde la app → Microsip</h3>\n    <p style=\"font-size:12px; color:var(--muted); margin-bottom:8px;\">Al aprobarlas se registran en Microsip (Nómina → vacaciones) y se descuentan de su periodo. Si Microsip no las acepta, se quedan pendientes con el motivo.</p>\n    <table class=\"users\">\n      <thead><tr><th>Persona</th><th>No. emp.</th><th>Desde</th><th>Días</th><th>Nota</th><th>Estado</th><th></th></tr></thead>\n      <tbody>\n        ${listaMs.map(v => `\n          <tr>\n            <td>${escapeHtml(v.usuario_nombre)}</td>\n            <td>${escapeHtml(v.numero_empleado || '—')}</td>\n            <td>${v.fecha_inicio}</td>\n            <td>${v.dias}</td>\n            <td style=\"max-width:220px;\">${v.descripcion ? escapeHtml(v.descripcion) : '—'}${v.resuelto_por_nombre ? `<div style=\"font-size:10px; color:var(--muted);\">Resuelta por ${escapeHtml(v.resuelto_por_nombre)}</div>` : ''}${v.microsip_error ? `<div style=\"font-size:11px; color:#e8a33d;\">⚠️ ${escapeHtml(v.microsip_error)}</div>` : ''}</td>\n            <td>${BADGE_ESTADO_VAC[v.estado] || escapeHtml(v.estado)}${v.estado === 'aprobada' && v.microsip_vacacion_id ? '<div style=\"font-size:10px; color:var(--muted);\">en Microsip</div>' : ''}</td>\n            <td style=\"display:flex; gap:6px;\">\n              ${v.estado === 'pendiente' ? `\n                <button class=\"primary\" style=\"padding:5px 10px; font-size:11px;\" onclick=\"resolverVacacionMicrosipUI(${v.id}, 'aprobada', this)\">✅ ${v.microsip_error ? 'Reintentar' : 'Aprobar'}</button>\n                <button class=\"danger\" style=\"padding:5px 10px; font-size:11px;\" onclick=\"resolverVacacionMicrosipUI(${v.id}, 'rechazada', this)\">❌ Rechazar</button>\n              ` : ''}\n            </td>\n          </tr>`).join('') || '<tr><td colspan=\"7\" class=\"empty-col\">— sin solicitudes —</td></tr>'}\n      </tbody>\n    </table>\n    <h3 style=\"margin:18px 0 6px;\">Con ajuste de antigüedad</h3>` : '';\n  cont.innerHTML = `\n    <p style=\"font-size:12px; color:var(--muted); margin-bottom:12px;\">\n      Vacaciones pedidas desde la app. Las de <b>Microsip</b> se registran allá al aprobarlas; las de <b>ajuste de antigüedad</b>\n      (Empleados (Microsip) → Ver ficha → Ajuste de antigüedad) solo se descuentan aquí. Nada se descuenta hasta que las apruebes.\n    </p>\n    <div class=\"admin-tabs\" style=\"margin-bottom:12px;\">\n      <button class=\"admin-tab ${VACACIONES_AJUSTE_FILTRO === 'pendiente' ? 'active' : ''}\" onclick=\"VACACIONES_AJUSTE_FILTRO='pendiente'; renderVacacionesAjusteRH();\">⏳ Pendientes</button>\n"
