   "          </table>\n        ` : ''}\n        <p style=\"font-size:11px; color:var(--muted); margin-top:10px;\">Directo de Microsip — el mismo dato que RH.</p>\n        ${datos.puede_solicitar ? `\n          <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--muted); text-transform:uppercase; display:block; margin-top:14px;\">Pedir vacaciones (te quedan ${datos.dias_para_pedir})</label>\n          <p style=\"font-size:11px; color:var(--muted); margin:4px 0 6px;\">RH la aprueba y en ese momento queda registrada en Microsip.</p>\n          <div class=\"row-2\" style=\"margin-top:6px;\">\n            <div class=\"field\"><label>Primer día</label><input type=\"date\" id=\"mv_fecha\" /></div>\n            <div class=\"field\"><label>Días</label><input type=\"number\" id=\"mv_dias\" value=\"1\" min=\"0.5\" step=\"0.5\" /></div>\n          </div>\n          <div class=\"field\"><label>Nota (opcional)</label><input id=\"mv_desc\" placeholder=\"ej. Vacaciones de fin de año\" /></div>\n          <button class=\"primary\" style=\"width:100%;\" onclick=\"solicitarMisVacacionesUI(this)\">Solicitar</button>\n          <div id=\"mvError\" class=\"error-msg\"></div>` : ''}\n        ${(datos.solicitudes || []).length ? `\n          <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--muted); text-transform:uppercase; display:block; margin-top:16px;\">Mis solicitudes</label>\n          <table class=\"users\">\n            <thead><tr><th>Desde</th><th>Días</th><th>Nota</th><th>Estado</th><th></th></tr></thead>\n            <tbody>${datos.solicitudes.map(r => `<tr><td>${r.fecha_inicio}</td><td>${r.dias}</td><td>${r.descripcion ? escapeHtml(r.descripcion) : '—'}${r.respuesta_admin ? `<div style=\"font-size:11px; color:var(--muted);\">RH: ${escapeHtml(r.respuesta_admin)}</div>` : ''}</td><td>${{pendiente:'⏳ Pendiente', aprobada:'✅ Aprobada', rechazada:'❌ Rechazada', cancelada:'Cancelada'}[r.estado] || escapeHtml(r.estado)}</td><td>${r.estado === 'pendiente' ? `<button class=\"secondary\" style=\"padding:3px 8px; font-size:11px;\" onclick=\"cancelarMiSolicitudVacacionesUI(${r.id}, this)\">Cancelar</button>` : ''}</td></tr>`).join('')}</tbody>\n          </table>` : ''}\n      `}\n    `;\n  } catch (e) {\n    document.getElementById('modalContent').innerHTML = `<button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button><h2>🏖️ Mis vacaciones</h2><p style=\"color:var(--copper);\">${escapeHtml(e.message)}</p>`;\n  }\n}\n\nasync function cancelarMiSolicitudVacacionesUI(id, btn) {\n  if (!confirm('¿Cancelar esta solicitud de vacaciones?')) return;\n  await conBloqueoDeBoton(btn, async () => {\n    try { await api(`/api/mis-vacaciones/solicitudes/${id}/cancelar`, { method: 'POST' }); } catch (e) { alert(e.message); }\n    await abrirMisVacaciones();\n  });\n}\n\nasync function solicitarMisVacacionesUI(boton) {\n"
